left_rows = sql_data.get('v23_sc16_pm_026_left', [])
right_rows = sql_data.get('v23_sc16_pm_026_right', [])
left_totals = {}
right_totals = {}
for row in left_rows:
    k = row.get('line_key')
    if k != None:
        left_totals[k] = left_totals.get(k, 0) + (row.get('output_amount', 0) or 0)
for row in right_rows:
    k = row.get('line_key')
    if k != None:
        right_totals[k] = right_totals.get(k, 0) + (row.get('rework_units', 0) or 0)
keys = []
for k in left_totals:
    keys.append(k)
for k in right_totals:
    if k not in keys:
        keys.append(k)
for k in keys:
    net = left_totals.get(k, 0) - right_totals.get(k, 0)
    out('production_balance').append({'line_key': k, 'net_value': net})
```

